<p>في الفترة نفسها تقريبًا، 1 إلى 22 يونيو 2026، سجلت حملات الرسائل على Meta عدد 602 محادثة واتساب وماسنجر بتكلفة بين 3.72 و3.83 ريال، بإنفاق 2,281 ريالًا. Google يلتقط من يبحث عن العلاج الآن، وMeta يصل إلى من يحتاج الخدمة ولم يبحث بعد. المحادثة الرخيصة ليست هدفًا بحد ذاتها، ولهذا أتابع كم منها صار حجزًا، كما شرحت في <a href="/blog/whatsapp-leads-measurement/">مقال قياس طلبات واتساب</a>.</p>
