<p>وفي متجر إلكتروني سعودي سجلت حملة المبيعات 163 عملية شراء بتكلفة 120.75 ريال. قبل أي قرار طابقت المشتريات مع طلبات المتجر، لأن مدير الإعلانات يعرض ما تنسبه Meta لنفسها.</p>
