  <li><strong>كرّر مع اللي جاب، ووقّف اللي ما جاب.</strong> بعدها فكّر تاخذ محتوى المشهور الناجح وتستخدمه كإعلان ممول على حسابك، بإذنه، وهنا تقدر تتحكم بالاستهداف والميزانية.</li>
