<p>إذا الجواب «منتج معين»، المشكلة في المنتج أو صوره. وإذا «قناة معينة»، راجع الإعلان والجمهور في هذي القناة. وإذا المرتجع موزع على كل شي، غالبًا المشكلة في جدول المقاسات أو سياسة الاسترجاع نفسها.</p>

